-- Original: server/internal/quest/upstream/projecteq/mischiefplane/a_white_stallion.lua (sha256 3e561e0183324f9484b3a9766682095411b6ca8d17868542121565295e3f4d26)
-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- The restored white Lithiniath appears at the stallion surface instead of the upstream hardcoded coordinates. No quest-state or new movement engine is needed.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Emote("stares at " .. e.other:GetCleanName() .. " unblinking with colorless eyes.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 22856 }) then
    e.self:Say("The madness has fled my mind and I am once again whole! Give Gelistial my regards, I must leave this place and try to quell the madness I have inflicted.")
    e.other:SummonItem(24869)
    e.other:AddEXP(100)
    eq.spawn2(126612, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading())
    eq.depop_with_timer()
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end

function event_spawn(e)
	eq.depop(126612); -- despawns White Lithiniath if remained up 
end
